import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String a = sc.next();
        String b = sc.next();

        String[] dirs = {"norte", "leste", "sul", "oeste"};

        int ia = 0, ib = 0;
        for (int i = 0; i < 4; i++) {
            if (dirs[i].equals(a)) ia = i;
            if (dirs[i].equals(b)) ib = i;
        }

        int d = Math.abs(ia - ib);
        int ans = Math.min(d, 4 - d) * 90;

        System.out.println(ans);
    }
}
